def build():
    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    with open(OUT, 'w', encoding='utf-8') as f:
        json.dump(SOLVED, f, ensure_ascii=False, indent=2)
    print(f'Built {len(SOLVED)} items → {OUT}')

    # Summary by chapter
    from collections import Counter
    ch_counts = Counter(item['chapter'] for item in SOLVED)
    for ch in sorted(ch_counts):
        print(f'  Chapter {ch}: {ch_counts[ch]} items')

    type_counts = Counter(item['type'] for item in SOLVED)
    for t in ['mcq', 'short', 'descriptive']:
        print(f'  {t}: {type_counts.get(t, 0)} items')


if __name__ == '__main__':
    build()
